#!/usr/bin/env bash
# Historical launch reference only; not a runnable recipe.
# Generated by scripts/package_q4_cloud_campaign.py; dedicated Q4 copy.
set -euo pipefail

CLUSTER_ID=${1:?Missing Condor ClusterId}
PROC_ID=${2:?Missing Condor ProcId}

GCS_PREPARED_PREFIX=${GCS_PREPARED_PREFIX:?Missing GCS_PREPARED_PREFIX}
GCS_OUTPUT_PREFIX=${GCS_OUTPUT_PREFIX:?Missing GCS_OUTPUT_PREFIX}
PROJECT_ARCHIVE=${PROJECT_ARCHIVE:-heptokens-google-data-grl-variants-b300-v2.tar.gz}
Q4_UPDATE_ARCHIVE=${Q4_UPDATE_ARCHIVE:-heptokens-q4-campaign-update.tar.gz}
EXPECTED_Q4_UPDATE_SHA256=${EXPECTED_Q4_UPDATE_SHA256:?Missing EXPECTED_Q4_UPDATE_SHA256}
MASK_PROB=${MASK_PROB:?Missing MASK_PROB}
EXPECTED_GLOBAL_STEPS=${EXPECTED_GLOBAL_STEPS:?Missing EXPECTED_GLOBAL_STEPS}
SERVICE_ACCOUNT_KEY=${SERVICE_ACCOUNT_KEY:-example-worker-service-account.json}
B300_PIXI_MANIFEST=${B300_PIXI_MANIFEST:-pixi-b300.toml}
B300_PIXI_LOCK=${B300_PIXI_LOCK:-pixi-b300.lock}
EXPECTED_ARCHIVE_SHA256=${EXPECTED_ARCHIVE_SHA256:-}
EXPECTED_MANIFEST_SHA256=${EXPECTED_MANIFEST_SHA256:-}
EXPECTED_TRAIN_ROWS=${EXPECTED_TRAIN_ROWS:-194491678}
EXPECTED_VAL_ROWS=${EXPECTED_VAL_ROWS:-21603969}
EXPECTED_TRAIN_SHARDS=${EXPECTED_TRAIN_SHARDS:-3898}
EXPECTED_VAL_SHARDS=${EXPECTED_VAL_SHARDS:-440}
SEED=${SEED:-42}
EPOCHS=${EPOCHS:-10}
BATCH_SIZE=${BATCH_SIZE:-448}
NUM_WORKERS=${NUM_WORKERS:-3}
NUM_DEVICES=${NUM_DEVICES:-8}
TRAINER_STRATEGY=${TRAINER_STRATEGY:-ddp}
CUDA_VISIBLE_DEVICE_LIST=${CUDA_VISIBLE_DEVICE_LIST:-}
VOCAB_SIZE=${VOCAB_SIZE:-262660}
MAX_QUANTIZERS=${MAX_QUANTIZERS:-4}
QUANTIZER_EMBEDDING_DIM=${QUANTIZER_EMBEDDING_DIM:-64}
OBJECT_PROJECTION_MODE=${OBJECT_PROJECTION_MODE:-identity}
SHUFFLE_BUFFER_SIZE=${SHUFFLE_BUFFER_SIZE:-8192}
STREAM_BATCH_SIZE=${STREAM_BATCH_SIZE:-4096}
LIMIT_TRAIN_BATCHES=${LIMIT_TRAIN_BATCHES:-1.0}
LIMIT_VAL_BATCHES=${LIMIT_VAL_BATCHES:-500}
CHECKPOINT_SYNC_INTERVAL=${CHECKPOINT_SYNC_INTERVAL:-900}
RESUME_CHECKPOINT_URI=${RESUME_CHECKPOINT_URI:-}
PROJECT_NAME=${PROJECT_NAME:-atlas_event_foundation_q4_masking_study}
NETWORK_NAME=${NETWORK_NAME:?Missing NETWORK_NAME}
PYTORCH_VERSION=${PYTORCH_VERSION:-2.11.0}
TORCHVISION_VERSION=${TORCHVISION_VERSION:-0.26.0}
TORCHAUDIO_VERSION=${TORCHAUDIO_VERSION:-2.11.0}
PYTORCH_INDEX_URL=${PYTORCH_INDEX_URL:-https://download.pytorch.org/whl/cu130}

SCRATCH_DIR=${_CONDOR_SCRATCH_DIR:-$PWD}
WORK_DIR="$SCRATCH_DIR/work"
PREPARED_DIR="$WORK_DIR/prepared"
RESULTS_DIR="$WORK_DIR/results"
PIXI_HOME="$WORK_DIR/.pixi"
KEY_FILE="$SCRATCH_DIR/$SERVICE_ACCOUNT_KEY"
B300_PIXI_MANIFEST_FILE="$SCRATCH_DIR/$B300_PIXI_MANIFEST"
B300_PIXI_LOCK_FILE="$SCRATCH_DIR/$B300_PIXI_LOCK"
DESTINATION="$GCS_OUTPUT_PREFIX/cluster_${CLUSTER_ID}_proc_${PROC_ID}"
GPU_MONITOR_PID=
CHECKPOINT_SYNC_PID=

export XDG_CACHE_HOME="$WORK_DIR/cache"
export XDG_CONFIG_HOME="$WORK_DIR/config"
export UV_CACHE_DIR="$XDG_CACHE_HOME/uv"
export CLOUDSDK_CONFIG="$WORK_DIR/gcloud-config"
mkdir -p "$PREPARED_DIR" "$RESULTS_DIR" "$XDG_CACHE_HOME" \
  "$XDG_CONFIG_HOME" "$UV_CACHE_DIR" "$CLOUDSDK_CONFIG"
exec > >(tee -a "$RESULTS_DIR/setup.log") 2>&1

upload_results() {
  local rc=$?
  trap - EXIT
  set +e
  if [[ -n "$GPU_MONITOR_PID" ]]; then
    kill "$GPU_MONITOR_PID" 2>/dev/null
    wait "$GPU_MONITOR_PID" 2>/dev/null
  fi
  if [[ -n "$CHECKPOINT_SYNC_PID" ]]; then
    kill "$CHECKPOINT_SYNC_PID" 2>/dev/null
    wait "$CHECKPOINT_SYNC_PID" 2>/dev/null
  fi
  {
    echo "exit_code=$rc"
    echo "finished=$(date --iso-8601=seconds)"
    echo "worker=$(hostname --fqdn 2>/dev/null || hostname)"
    echo "seed=$SEED"
    echo "epochs=$EPOCHS"
    echo "batch_size_per_gpu=$BATCH_SIZE"
    echo "num_devices=$NUM_DEVICES"
    echo "cuda_visible_device_list=${CUDA_VISIBLE_DEVICE_LIST:-scheduler_default}"
    echo "global_batch_size=$((BATCH_SIZE * NUM_DEVICES))"
    echo "limit_train_batches=$LIMIT_TRAIN_BATCHES"
    echo "limit_val_batches=$LIMIT_VAL_BATCHES"
    echo "vocab_size=$VOCAB_SIZE"
    echo "max_quantizers=$MAX_QUANTIZERS"
    echo "quantizer_embedding_dim=$QUANTIZER_EMBEDDING_DIM"
    echo "object_projection_mode=$OBJECT_PROJECTION_MODE"
    echo "mask_prob=$MASK_PROB"
    echo "ensure_masked_physical_object_per_event=true"
    echo "prepared_prefix=$GCS_PREPARED_PREFIX"
    echo "masking_update_sha256=$EXPECTED_Q4_UPDATE_SHA256"
    echo "expected_global_steps=$EXPECTED_GLOBAL_STEPS"
    echo "pytorch_version=$PYTORCH_VERSION"
    echo "torchvision_version=$TORCHVISION_VERSION"
    echo "torchaudio_version=$TORCHAUDIO_VERSION"
    echo "pytorch_index_url=$PYTORCH_INDEX_URL"
    echo "manifest_sha256=$EXPECTED_MANIFEST_SHA256"
    [[ -n "$EXPECTED_ARCHIVE_SHA256" ]] && \
      echo "archive_sha256=$EXPECTED_ARCHIVE_SHA256"
  } > "$RESULTS_DIR/job_status.txt"

  # Publish the small CSVs at the top level even if a smoke ends before the
  # first periodic sync. Leave the large checkpoint in its original location.
  for live_name in live_metrics.csv masking_audit.csv; do
    live_file=$(find "$RESULTS_DIR" -type f -name "$live_name" -print -quit)
    if [[ -n "$live_file" && "$live_file" != "$RESULTS_DIR/$live_name" ]]; then
      cp "$live_file" "$RESULTS_DIR/$live_name"
    fi
  done

  echo "Uploading results to $DESTINATION"
  gcloud storage rsync --recursive "$RESULTS_DIR" "$DESTINATION"
  local upload_rc=$?
  rm -rf "$CLOUDSDK_CONFIG"
  if [[ $rc -eq 0 && $upload_rc -ne 0 ]]; then rc=$upload_rc; fi
  exit "$rc"
}
trap upload_results EXIT

[[ -s "$KEY_FILE" ]] || {
  echo "Missing service-account key: $KEY_FILE" >&2
  exit 2
}
[[ -s "$B300_PIXI_MANIFEST_FILE" ]] || {
  echo "Missing B300 Pixi manifest: $B300_PIXI_MANIFEST_FILE" >&2
  exit 2
}
[[ -s "$B300_PIXI_LOCK_FILE" ]] || {
  echo "Missing B300 Pixi lock file: $B300_PIXI_LOCK_FILE" >&2
  exit 2
}
chmod 600 "$KEY_FILE"
gcloud auth activate-service-account --key-file="$KEY_FILE"

if [[ -n "$CUDA_VISIBLE_DEVICE_LIST" ]]; then
  export CUDA_DEVICE_ORDER=PCI_BUS_ID
  export CUDA_VISIBLE_DEVICES="$CUDA_VISIBLE_DEVICE_LIST"
fi

echo "=== Grouped-CLS Q4 foundation pretraining ==="
echo "Started: $(date --iso-8601=seconds)"
echo "Worker: $(hostname --fqdn 2>/dev/null || hostname)"
echo "Scratch: $SCRATCH_DIR"
echo "Prepared input: $GCS_PREPARED_PREFIX"
echo "Results: $DESTINATION"
echo "Seed: $SEED"
echo "Epochs: $EPOCHS"
echo "Per-GPU batch: $BATCH_SIZE"
echo "GPU devices: $NUM_DEVICES"
echo "CUDA_VISIBLE_DEVICES: ${CUDA_VISIBLE_DEVICES:-scheduler default}"
echo "Global batch: $((BATCH_SIZE * NUM_DEVICES))"
echo "Trainer strategy: $TRAINER_STRATEGY"
echo "Train batches per epoch: $LIMIT_TRAIN_BATCHES"
echo "Validation batches: $LIMIT_VAL_BATCHES"
echo "Vocabulary size: $VOCAB_SIZE"
echo "Maximum quantizers: $MAX_QUANTIZERS"
echo "Quantizer embedding dimension: $QUANTIZER_EMBEDDING_DIM"
echo "Object projection mode: $OBJECT_PROJECTION_MODE"
echo "Mask probability: $MASK_PROB; per-event physical-object guarantee: true"
echo "B300 PyTorch runtime: torch=$PYTORCH_VERSION torchvision=$TORCHVISION_VERSION torchaudio=$TORCHAUDIO_VERSION"
echo "B300 PyTorch index: $PYTORCH_INDEX_URL"
nvidia-smi -L

# Respect Condor assignments; nvidia-smi alone can list other jobs' GPUs.
GPU_SELECTION_ARGS=()
if [[ -n "${CUDA_VISIBLE_DEVICES:-}" ]]; then
  GPU_SELECTION_ARGS=("--id=$CUDA_VISIBLE_DEVICES")
fi

GPU_LOG="$RESULTS_DIR/gpu_memory.csv"
echo "timestamp,index,name,memory_used_MiB,memory_total_MiB,gpu_utilization_percent" \
  > "$GPU_LOG"
(
  while true; do
    nvidia-smi "${GPU_SELECTION_ARGS[@]}" \
      --query-gpu=timestamp,index,name,memory.used,memory.total,utilization.gpu \
      --format=csv,noheader,nounits >> "$GPU_LOG"
    sleep 5
  done
) &
GPU_MONITOR_PID=$!

echo "Downloading and validating the prepared Q4 manifest"
gcloud storage cp "$GCS_PREPARED_PREFIX/manifest.json" "$PREPARED_DIR/manifest.json"
gcloud storage cp "$GCS_PREPARED_PREFIX/manifest.sha256" "$WORK_DIR/manifest.sha256"
FINALIZED_MANIFEST_SHA=$(tr -d '\r\n' < "$WORK_DIR/manifest.sha256")
[[ "$FINALIZED_MANIFEST_SHA" =~ ^[0-9a-f]{64}$ ]] || exit 2
if [[ -n "$EXPECTED_MANIFEST_SHA256" && "$EXPECTED_MANIFEST_SHA256" != "$FINALIZED_MANIFEST_SHA" ]]; then
  echo "Finalized Q4 manifest checksum differs from submitted checksum" >&2; exit 2;
fi
EXPECTED_MANIFEST_SHA256="$FINALIZED_MANIFEST_SHA"

ACTUAL_MANIFEST_SHA256=$(sha256sum "$PREPARED_DIR/manifest.json" | awk '{print $1}')
if [[ "$ACTUAL_MANIFEST_SHA256" != "$EXPECTED_MANIFEST_SHA256" ]]; then
  echo "Manifest checksum mismatch: expected=$EXPECTED_MANIFEST_SHA256 actual=$ACTUAL_MANIFEST_SHA256" >&2
  exit 2
fi

python3 - "$PREPARED_DIR/manifest.json" \
  "$EXPECTED_TRAIN_ROWS" "$EXPECTED_VAL_ROWS" \
  "$EXPECTED_TRAIN_SHARDS" "$EXPECTED_VAL_SHARDS" <<'PY'
import json
import sys

path, train_rows, val_rows, train_shards, val_shards = sys.argv[1:]
manifest = json.load(open(path))
expected = {
    "seed": 42,
    "train_rows": int(train_rows),
    "val_rows": int(val_rows),
    "train_shards": int(train_shards),
    "val_shards": int(val_shards),
}
errors = [
    f"{key}: observed={manifest.get(key)!r}, expected={value!r}"
    for key, value in expected.items()
    if manifest.get(key) != value
]
if errors:
    raise SystemExit("Prepared-data manifest mismatch:\n  " + "\n  ".join(errors))
print("Prepared-data manifest matches the Q4 production dataset")
print(json.dumps(expected, indent=2))
PY

gcloud storage rsync --recursive "$GCS_PREPARED_PREFIX/train" "$PREPARED_DIR/train"
gcloud storage rsync --recursive "$GCS_PREPARED_PREFIX/val" "$PREPARED_DIR/val"

ACTUAL_TRAIN_SHARDS=$(find "$PREPARED_DIR/train" -type f -name '*.parquet' | wc -l)
ACTUAL_VAL_SHARDS=$(find "$PREPARED_DIR/val" -type f -name '*.parquet' | wc -l)
if [[ "$ACTUAL_TRAIN_SHARDS" -ne "$EXPECTED_TRAIN_SHARDS" || \
      "$ACTUAL_VAL_SHARDS" -ne "$EXPECTED_VAL_SHARDS" ]]; then
  echo "Downloaded shard-count mismatch: train=$ACTUAL_TRAIN_SHARDS val=$ACTUAL_VAL_SHARDS" >&2
  exit 2
fi

[[ -s "$PROJECT_ARCHIVE" ]] || {
  echo "Missing project archive: $PROJECT_ARCHIVE" >&2
  exit 2
}
ACTUAL_ARCHIVE_SHA256=$(sha256sum "$PROJECT_ARCHIVE" | awk '{print $1}')
if [[ -n "$EXPECTED_ARCHIVE_SHA256" && \
      "$ACTUAL_ARCHIVE_SHA256" != "$EXPECTED_ARCHIVE_SHA256" ]]; then
  echo "Project archive checksum mismatch: expected=$EXPECTED_ARCHIVE_SHA256 actual=$ACTUAL_ARCHIVE_SHA256" >&2
  exit 2
fi
echo "Project archive SHA256: $ACTUAL_ARCHIVE_SHA256"

mkdir -p "$WORK_DIR/project"
tar -xzf "$PROJECT_ARCHIVE" -C "$WORK_DIR/project"
PYPROJECT_PATH=$(find "$WORK_DIR/project" -maxdepth 3 -type f -name pyproject.toml -print -quit)
[[ -n "$PYPROJECT_PATH" ]] || {
  echo "pyproject.toml not found in project archive" >&2
  exit 2
}
REPO_DIR=$(dirname "$PYPROJECT_PATH")

UPDATE_FILE="$SCRATCH_DIR/$Q4_UPDATE_ARCHIVE"
[[ -s "$UPDATE_FILE" ]] || { echo "Missing masking update archive" >&2; exit 2; }
UPDATE_SHA=$(sha256sum "$UPDATE_FILE" | awk '{print $1}')
[[ "$UPDATE_SHA" == "$EXPECTED_Q4_UPDATE_SHA256" ]] || {
  echo "Masking update checksum mismatch" >&2; exit 2;
}
# Apply only the masking update to this job's private extracted project.
tar -xzf "$UPDATE_FILE" -C "$REPO_DIR"
echo "Masking update SHA256: $UPDATE_SHA"
[[ -z "$RESUME_CHECKPOINT_URI" ]] || {
  echo "Controlled masking comparisons must start from scratch" >&2; exit 2;
}

if command -v pixi >/dev/null 2>&1; then
  PIXI=$(command -v pixi)
else
  export PIXI_HOME
  # The installer also downloads a GitHub release asset. Retry the complete
  # installer, not only install.sh, so an HTTP 500 from that asset is covered.
  for install_attempt in 1 2 3; do
    echo "Installing Pixi: attempt $install_attempt/3"
    if curl -fsSL https://pixi.sh/install.sh | sh; then
      break
    fi
    if [[ "$install_attempt" -eq 3 ]]; then
      echo "Pixi installation failed after three attempts" >&2
      exit 1
    fi
    sleep 10
  done
  PIXI="$PIXI_HOME/bin/pixi"
  [[ -x "$PIXI" ]] || { echo "Pixi installer did not create $PIXI" >&2; exit 1; }
fi

cd "$REPO_DIR"
if [[ -f pixi.lock ]]; then
  mv pixi.lock "$RESULTS_DIR/pixi.lock.original-a100"
fi
cp "$B300_PIXI_MANIFEST_FILE" "$REPO_DIR/pixi.toml"
cp "$B300_PIXI_LOCK_FILE" "$REPO_DIR/pixi.lock"
export PYTHONPATH="$REPO_DIR/src${PYTHONPATH:+:$PYTHONPATH}"

"$PIXI" install \
  --manifest-path "$REPO_DIR/pixi.toml" \
  --platform linux-64 \
  --locked \
  2>&1 | tee "$RESULTS_DIR/pixi_install.log"

PIXI_ENV_LIB="$REPO_DIR/.pixi/envs/default/lib"
[[ -s "$PIXI_ENV_LIB/libstdc++.so.6" ]] || {
  echo "Pixi C++ runtime is missing: $PIXI_ENV_LIB/libstdc++.so.6" >&2
  exit 2
}
PIXI_LD_LIBRARY_PATH="$PIXI_ENV_LIB${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"
PIXI_RUN=(
  env "LD_LIBRARY_PATH=$PIXI_LD_LIBRARY_PATH"
  "$PIXI" run
  --manifest-path "$REPO_DIR/pixi.toml"
  --platform linux-64
  --locked
)

"${PIXI_RUN[@]}" python - "$NUM_DEVICES" <<'PY' | tee "$RESULTS_DIR/pytorch_runtime.txt"
import sys
import torch
import torchaudio
import torchvision

print(f"torch={torch.__version__}")
print(f"torchvision={torchvision.__version__}")
print(f"torchaudio={torchaudio.__version__}")
print(f"torch_cuda={torch.version.cuda}")
print(f"nccl={torch.cuda.nccl.version()}")
print(f"cuda_available={torch.cuda.is_available()}")
print(f"cuda_device_count={torch.cuda.device_count()}")
print(f"cuda_arch_list={torch.cuda.get_arch_list()}")
for index in range(torch.cuda.device_count()):
    print(
        f"gpu[{index}]={torch.cuda.get_device_name(index)} "
        f"capability={torch.cuda.get_device_capability(index)}"
    )
if torch.cuda.device_count() != int(sys.argv[1]):
    raise SystemExit(f"Assigned CUDA devices: {torch.cuda.device_count()}, expected {sys.argv[1]}")
if not torch.cuda.is_available():
    raise SystemExit("CUDA is not available in the upgraded PyTorch runtime")
if not torch.__version__.startswith("2.11.0"):
    raise SystemExit(f"Unexpected PyTorch version: {torch.__version__}")
if torch.version.cuda != "13.0":
    raise SystemExit(f"Unexpected PyTorch CUDA runtime: {torch.version.cuda}")
probe = torch.ones(1, device="cuda:0") * 2
if probe.item() != 2:
    raise SystemExit("Single-GPU CUDA calculation failed")
PY

echo "Running a $NUM_DEVICES-GPU NCCL all-reduce preflight"
NCCL_DEBUG=INFO "${PIXI_RUN[@]}" torchrun \
  --standalone \
  --nproc_per_node="$NUM_DEVICES" \
  "$SCRATCH_DIR/b300_nccl_preflight.py" \
  2>&1 | tee "$RESULTS_DIR/nccl_preflight.log"

cp pixi.lock "$RESULTS_DIR/pixi.lock.resolved"
"${PIXI_RUN[@]}" python -m unittest discover -s tests \
  -p 'test_grouped_object_masking.py' -v \
  2>&1 | tee "$RESULTS_DIR/masking_unit_tests.log"

"${PIXI_RUN[@]}" python scripts/q4_data_grl_campaign.py validate-prepared   --prepared-dir "$PREPARED_DIR" 2>&1 | tee "$RESULTS_DIR/q4_data_validation.txt"
TOKEN_VOCABULARY_FILE="$RESULTS_DIR/token_vocabulary.json"
read -r DETECTED_VOCAB_SIZE DETECTED_MAX_QUANTIZERS DETECTED_SEQUENCE_LENGTH \
  DETECTED_QUANTIZERS_PER_POSITION < <(
  "${PIXI_RUN[@]}" python - "$PREPARED_DIR" "$TOKEN_VOCABULARY_FILE" <<'PY'
import json
import sys
from pathlib import Path

import pyarrow.parquet as pq

prepared = Path(sys.argv[1])
first = sorted((prepared / "train").glob("*.parquet"))[0]
parquet = pq.ParquetFile(first)
metadata = parquet.schema_arrow.metadata or {}
vocabulary = json.loads(metadata[b"heptokens_token_vocabulary"])
validation_first = sorted((prepared / "val").glob("*.parquet"))[0]
validation_metadata = pq.ParquetFile(validation_first).schema_arrow.metadata or {}
validation_vocabulary = json.loads(validation_metadata[b"heptokens_token_vocabulary"])
if validation_vocabulary != vocabulary:
    raise ValueError("Prepared train and validation token vocabularies disagree")
if not vocabulary.get("objects"):
    raise ValueError("Prepared Q4 token vocabulary has no physical object definitions")
Path(sys.argv[2]).write_text(json.dumps(vocabulary, indent=2) + "\n")
tokens = next(parquet.iter_batches(batch_size=1, columns=["tokens"]))["tokens"][0].as_py()
print(
    vocabulary["vocab_size"],
    vocabulary["max_quantizers"],
    len(tokens),
    len(tokens[0]),
)
PY
)

if [[ "$DETECTED_VOCAB_SIZE" -ne "$VOCAB_SIZE" || \
      "$DETECTED_MAX_QUANTIZERS" -ne "$MAX_QUANTIZERS" || \
      "$DETECTED_SEQUENCE_LENGTH" -ne 256 || \
      "$DETECTED_QUANTIZERS_PER_POSITION" -ne "$MAX_QUANTIZERS" ]]; then
  echo "Q4 vocabulary/shape mismatch: vocab=$DETECTED_VOCAB_SIZE max_q=$DETECTED_MAX_QUANTIZERS sequence=$DETECTED_SEQUENCE_LENGTH per_position=$DETECTED_QUANTIZERS_PER_POSITION" >&2
  exit 2
fi
echo "Verified Q4 input: vocab=$DETECTED_VOCAB_SIZE shape=[$DETECTED_SEQUENCE_LENGTH,$DETECTED_QUANTIZERS_PER_POSITION]"
echo "Physical-object vocabulary: $TOKEN_VOCABULARY_FILE (read from staged Parquet metadata)"

# Exercise scripts/train.py without its automatic metadata bridge, as in the
# pinned base archive. Both policies must train and reload portable checkpoints.
"${PIXI_RUN[@]}" python -m unittest discover -s tests \
  -p 'test_grouped_masking_metadata.py' -v \
  2>&1 | tee "$RESULTS_DIR/masking_metadata_tests.log"

export HYDRA_FULL_ERROR=1
export WANDB_MODE=offline
export WANDB_INIT_TIMEOUT=300
export WANDB_SILENT=true
export PYTHONUNBUFFERED=1
export PYTORCH_CUDA_ALLOC_CONF=expandable_segments:True
export OMP_NUM_THREADS=1
export MKL_NUM_THREADS=1
export OPENBLAS_NUM_THREADS=1
export NCCL_DEBUG=${NCCL_DEBUG:-WARN}
export TORCH_NCCL_ASYNC_ERROR_HANDLING=1

RESUME_ARGS=()
if [[ -n "$RESUME_CHECKPOINT_URI" ]]; then
  RESUME_DIR="$WORK_DIR/resume"
  RESUME_CHECKPOINT="$RESUME_DIR/last.ckpt"
  mkdir -p "$RESUME_DIR"
  gcloud storage cp "$RESUME_CHECKPOINT_URI" "$RESUME_CHECKPOINT"
  [[ -s "$RESUME_CHECKPOINT" ]] || {
    echo "Resume checkpoint is missing or empty" >&2
    exit 2
  }
  RESUME_ARGS+=("ckpt_path=$RESUME_CHECKPOINT")
fi

(
  while sleep "$CHECKPOINT_SYNC_INTERVAL"; do
    [[ -f "$RESULTS_DIR/training.log" ]] && \
      gcloud storage cp "$RESULTS_DIR/training.log" "$DESTINATION/training.log" || true
    [[ -f "$GPU_LOG" ]] && \
      gcloud storage cp "$GPU_LOG" "$DESTINATION/gpu_memory.csv" || true
    masking_audit=$(find "$RESULTS_DIR" -type f -name masking_audit.csv -print -quit)
    [[ -n "$masking_audit" ]] && \
      gcloud storage cp "$masking_audit" "$DESTINATION/masking_audit.csv" || true
    live_metrics=$(find "$RESULTS_DIR" -type f -name live_metrics.csv -print -quit)
    [[ -n "$live_metrics" ]] && \
      gcloud storage cp "$live_metrics" "$DESTINATION/live_metrics.csv" || true
    checkpoint=$(find "$RESULTS_DIR" -type f -name last.ckpt -print -quit)
    [[ -n "$checkpoint" ]] || continue
    first=$(stat -c '%s:%Y' "$checkpoint" 2>/dev/null) || continue
    sleep 5
    second=$(stat -c '%s:%Y' "$checkpoint" 2>/dev/null) || continue
    [[ "$first" == "$second" ]] || continue
    gcloud storage cp "$checkpoint" "$DESTINATION/checkpoints/last.ckpt" || true
  done
) &
CHECKPOINT_SYNC_PID=$!

"${PIXI_RUN[@]}" python scripts/train.py \
  seed="$SEED" \
  datamodule=token_parquet_pretrain \
  datamodule.seed="$SEED" \
  model=foundation_grouped_q4_direct_data_grl_pretrain \
  callbacks=pretrain_masking_study \
  project_name="$PROJECT_NAME" \
  network_name="$NETWORK_NAME" \
  logger.offline=true \
  output_dir="$RESULTS_DIR" \
  datamodule.prepared_dir="$PREPARED_DIR" \
  datamodule.batch_size="$BATCH_SIZE" \
  datamodule.num_workers="$NUM_WORKERS" \
  datamodule.stream_batch_size="$STREAM_BATCH_SIZE" \
  datamodule.shuffle_buffer_size="$SHUFFLE_BUFFER_SIZE" \
  model.hidden_dim=256 \
  model.num_heads=8 \
  model.num_layers=4 \
  model.dropout=0.1 \
  model.max_seq_length=256 \
  model.vocab_size="$VOCAB_SIZE" \
  model.max_quantizers="$MAX_QUANTIZERS" \
  model.quantizer_embedding_dim="$QUANTIZER_EMBEDDING_DIM" \
  model.object_projection_mode="$OBJECT_PROJECTION_MODE" \
  model.num_type_ids=12 \
  model.mask_token_id=3 \
  model.pad_token_id=0 \
  model.mask_prob="$MASK_PROB" \
  model.ensure_masked_physical_object_per_event=true \
  model.token_vocabulary_path="$TOKEN_VOCABULARY_FILE" \
  model.use_type_embedding=true \
  model.use_position_embedding=true \
  model.learning_rate=1.0e-4 \
  model.optimizer.lr=1.0e-4 \
  model.optimizer.weight_decay=1.0e-2 \
  model.scheduler.warmup_epochs=1 \
  model.scheduler.min_lr=1.0e-6 \
  trainer.max_epochs="$EPOCHS" \
  trainer.check_val_every_n_epoch=1 \
  trainer.val_check_interval=1.0 \
  trainer.limit_val_batches="$LIMIT_VAL_BATCHES" \
  +trainer.limit_train_batches="$LIMIT_TRAIN_BATCHES" \
  +trainer.log_every_n_steps=50 \
  trainer.accelerator=gpu \
  trainer.devices="$NUM_DEVICES" \
  trainer.num_nodes=1 \
  +trainer.strategy="$TRAINER_STRATEGY" \
  "${RESUME_ARGS[@]}" \
  2>&1 | tee "$RESULTS_DIR/training.log"

"${PIXI_RUN[@]}" python scripts/validate_grouped_masking_checkpoint.py \
  --results-dir "$RESULTS_DIR" --mask-prob "$MASK_PROB" \
  --epochs "$EPOCHS" --expected-global-steps "$EXPECTED_GLOBAL_STEPS" \
  --global-batch-size "$((BATCH_SIZE * NUM_DEVICES))" \
  --max-quantizers 4 --vocab-size 262660 --embedding-dim 64 \
  2>&1 | tee "$RESULTS_DIR/masking_checkpoint_check.txt"
echo "Q4 masking-study pretraining completed successfully"
